  addPoint(dynamicGroup, e2, RED, 0.112);
  addPoint(dynamicGroup, p2, GREEN, 0.112);
  addPoint(dynamicGroup, p1OnPlane2, CYAN, 0.098);

  const origin2 = plane2Center.clone().addScaledVector(n2, 0.10);
