userContent.text:
Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<button id="passStageBtn">Step through U-Net pass: idle</button>
<label>
  <span>Diffusion timestep t: <b id="timestepReadout">500</b></span>
  <input id="timestepSlider" type="range" min="0" max="1000" step="1" value="500">
</label>
<button id="inspectAttentionBtn">Inspect 16×16 self-attention</button>
<div id="stageCaption" style="font-size:11px;line-height:1.3;color:#333;background:#fff;border:1px solid #ddd;border-radius:4px;padding:5px 7px;">
  The U-Net pass is idle. Click the step button to follow the encoder, bottleneck, skip concatenations, and decoder.
</div>
<div style="display:flex;flex-wrap:wrap;gap:3px;margin-top:4px;">
  <button class="demoBtn" data-step="0">1 Input</button>
  <button class="demoBtn" data-step="1">2 Encoder</button>
  <button class="demoBtn" data-step="2">3 Attention</button>
  <button class="demoBtn" data-step="3">4 Bottleneck</button>
  <button class="demoBtn" data-step="4">5 Skips</button>
  <button class="demoBtn" data-step="5">6 Time</button>
</div>
<div id="demoNarration" style="font-size:11px;line-height:1.35;color:#333;background:#fff;border-left:3px solid #c87852;padding:4px 6px;">
  Choose a demo step or advance through the pass manually.
</div>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
// background → Scene background Color black
// noisy input image plane → PlaneGeometry with procedural DataTexture and black LineLoop outline
// noisy output image plane → PlaneGeometry with procedural DataTexture and black LineLoop outline
// feature volumes → BoxGeometry cuboids with copper front/top/side MeshBasicMaterial and EdgesGeometry outlines
// processing arrows → Line + ConeGeometry arrowheads along lower pipeline
// skip connections → orange Line polylines + ConeGeometry arrowheads
// Concatenate labels → HTML labels anchored above skip polylines
// timestep node → RingGeometry circle plus HTML label "t"
// time embedding baseline → blue Line
// time injection arrows → blue Line + ConeGeometry arrowheads from baseline to blocks
// legend arrows → short Line + ConeGeometry arrowheads near upper-left legend labels
// active highlight halo → dynamic EdgesGeometry LineSegments around current block bounds
// embedding badges → small PlaneGeometry squares whose colors update from sinusoidal timestep summary
// self-attention overlay → Group with PlaneGeometry panel, InstancedMesh 16×16 token grid, Line attention links, and plain residual-block cuboids

scene.background = new THREE.Color(0x000000);
renderer.setClearColor(0x000000, 1);
document.getElementById('btnReset').style.display = '';

const palette = {
  copperFront: 0xcf7b56,
  copperSide: 0x88411f,
  copperTop: 0xe08a61,
  outline: 0x000000,
  skip: 0xc87852,
  time: 0x547f92,
  glow: 0xffd166,
  dimBlue: 0x385f70
};

const root = new THREE.Group();
scene.add(root);

function makeMat(color, opacity = 1) {
  return new THREE.MeshBasicMaterial({
    color,
    transparent: true,
    opacity,
    side: THREE.DoubleSide,
    depthWrite: true
  });
}

function makeLineMat(color, opacity = 1, linewidth = 1) {
  return new THREE.LineBasicMaterial({
    color,
    transparent: true,
    opacity,
    linewidth
  });
}

function createNoiseTexture(size = 128) {
  const data = new Uint8Array(size * size * 4);
  for (let i = 0; i < size * size; i++) {
    const base = 120 + Math.floor(Math.random() * 95);
    const blue = Math.floor((Math.random() - 0.5) * 36);
    const pink = Math.floor((Math.random() - 0.5) * 30);
    data[4 * i + 0] = Math.max(0, Math.min(255, base + pink));
    data[4 * i + 1] = Math.max(0, Math.min(255, base + Math.floor(Math.random() * 20) - 10));
    data[4 * i + 2] = Math.max(0, Math.min(255, base + blue));
    data[4 * i + 3] = 255;
  }
  const tex = new THREE.DataTexture(data, size, size, THREE.RGBAFormat);
  tex.needsUpdate = true;
  tex.magFilter = THREE.NearestFilter;
  tex.minFilter = THREE.NearestFilter;
  return tex;
}

const allBlocks = [];
const blockById = {};
const badges = [];
const baselineY = -1.55;
const blockBaseY = -0.45;

function setObjectOpacity(obj, opacity) {
  obj.traverse((child) => {
    if (child.material) {
      if (Array.isArray(child.material)) {
        child.material.forEach((m) => {
          m.transparent = true;
          m.opacity = opacity;
        });
      } else {
        child.material.transparent = true;
        child.material.opacity = opacity;
      }
    }
  });
}

function createFeatureVolume(id, x, w, h, depth, label, options = {}) {
  const group = new THREE.Group();
  group.name = id;
  const geom = new THREE.BoxGeometry(w, h, depth);
  const mats = [
    makeMat(palette.copperSide),  // +x
    makeMat(palette.copperSide),  // -x
    makeMat(palette.copperTop),   // +y
    makeMat(0x6f3219),            // -y
    makeMat(palette.copperFront), // +z front
    makeMat(palette.copperSide)   // -z back
  ];
  const mesh = new THREE.Mesh(geom, mats);
  mesh.position.set(x, blockBaseY + h / 2, depth / 2);
  group.add(mesh);

  const edges = new THREE.LineSegments(
    new THREE.EdgesGeometry(geom),
    makeLineMat(palette.outline, 0.95)
  );
  edges.position.copy(mesh.position);
  group.add(edges);

  root.add(group);
  const entry = { id, group, mesh, edges, x, w, h, depth, label, kind: options.kind || 'residual' };
  allBlocks.push(entry);
  blockById[id] = entry;

  const badgeGeom = new THREE.PlaneGeometry(0.13, 0.13);
  const badgeMat = makeMat(0x7cc8ff, 0.92);
  const badge = new THREE.Mesh(badgeGeom, badgeMat);
  badge.position.set(x + w / 2 + 0.13, blockBaseY + h + 0.14, depth + 0.025);
  root.add(badge);
  badges.push({ mesh: badge, phase: badges.length * 0.71, block: entry });

  return entry;
}

function createImagePlane(id, x, side = 'left') {
  const w = 0.54, h = 2.35;
  const group = new THREE.Group();
  const geom = new THREE.PlaneGeometry(w, h);
  const mat = new THREE.MeshBasicMaterial({ map: createNoiseTexture(), side: THREE.DoubleSide });
  const plane = new THREE.Mesh(geom, mat);
  plane.position.set(x, blockBaseY + h / 2, 0.035);
  group.add(plane);

  const outlinePts = [
    new THREE.Vector3(-w / 2, -h / 2, 0.04), new THREE.Vector3(w / 2, -h / 2, 0.04),
    new THREE.Vector3(w / 2, h / 2, 0.04), new THREE.Vector3(-w / 2, h / 2, 0.04),
    new THREE.Vector3(-w / 2, -h / 2, 0.04)
  ];
  const outline = new THREE.Line(
    new THREE.BufferGeometry().setFromPoints(outlinePts),
    makeLineMat(palette.outline, 0.95)
  );
  outline.position.copy(plane.position);
  group.add(outline);
  root.add(group);

  const entry = { id, group, mesh: plane, x, w, h, depth: 0.04, label: side === 'left' ? 'noisy input' : 'predicted noise / output', kind: 'image' };
  allBlocks.push(entry);
  blockById[id] = entry;
  return entry;
}

const inputImg = createImagePlane('input256', -6.95, 'left');
const enc256a = createFeatureVolume('encoder256a', -6.33, 0.36, 2.35, 0.35, '256×256×128');
const enc256b = createFeatureVolume('encoder256b', -5.86, 0.36, 2.35, 0.35, '256×256×128');
const enc128 = createFeatureVolume('encoder128', -5.18, 0.44, 1.65, 0.35, '128×128×128');
const enc64 = createFeatureVolume('encoder64', -4.44, 0.54, 0.95, 0.48, '64×64×256');
const enc32 = createFeatureVolume('encoder32', -3.72, 0.62, 0.55, 0.48, '32×32×256');
const att16 = createFeatureVolume('attention16', -2.68, 1.08, 0.28, 0.62, '16×16×512 + attention', { kind: 'attention' });
const bottleneck = createFeatureVolume('bottleneck8', -1.36, 1.08, 0.18, 0.62, '8×8×512');
const dec16 = createFeatureVolume('decoder16', -0.08, 1.08, 0.18, 0.62, '16×16×512');
const dec32 = createFeatureVolume('decoder32', 1.16, 1.02, 0.28, 0.48, '32×32×256');
const dec64a = createFeatureVolume('decoder64a', 2.26, 0.62, 0.55, 0.48, '64×64×256');
const dec64b = createFeatureVolume('decoder64b', 2.88, 0.44, 0.95, 0.48, '64×64×256');
const dec128 = createFeatureVolume('decoder128', 3.54, 0.44, 1.65, 0.35, '128×128×128');
const dec256a = createFeatureVolume('decoder256a', 4.08, 0.36, 2.35, 0.35, '256×256×128');
const dec256b = createFeatureVolume('decoder256b', 4.55, 0.36, 2.35, 0.35, '256×256×128');
const dec256c = createFeatureVolume('decoder256c', 5.02, 0.36, 2.35, 0.35, '256×256×128');
const outputImg = createImagePlane('output256', 5.83, 'right');

function blockCenter(entry) {
  return new THREE.Vector3(entry.x, blockBaseY + entry.h / 2, entry.depth + 0.035);
}

function arrowBetween(p0, p1, color, opacity = 1, size = 0.12, parent = root) {
  const mat = makeLineMat(color, opacity);
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints([p0, p1]), mat);
  parent.add(line);
  const dir = p1.clone().sub(p0).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(size * 0.42, size, 16), makeMat(color, opacity));
  cone.position.copy(p1).add(dir.clone().multiplyScalar(-size * 0.45));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  parent.add(cone);
  return { line, cone, mat, coneMat: cone.material, p0, p1 };
}

function polyArrow(points, color, opacity = 1, size = 0.17, parent = root) {
  const mat = makeLineMat(color, opacity);
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(points), mat);
  parent.add(line);
  const p1 = points[points.length - 1];
  const p0 = points[points.length - 2];
  const dir = p1.clone().sub(p0).normalize();
  const cone = new THREE.Mesh(new THREE.ConeGeometry(size * 0.38, size, 16), makeMat(color, opacity));
  cone.position.copy(p1).add(dir.clone().multiplyScalar(-size * 0.45));
  cone.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  parent.add(cone);
  return { line, cone, mat, coneMat: cone.material, points };
}

const pipeline = [
  inputImg, enc256a, enc256b, enc128, enc64, enc32, att16, bottleneck,
  dec16, dec32, dec64a, dec64b, dec128, dec256a, dec256b, dec256c, outputImg
];

const mainArrows = [];
for (let i = 0; i < pipeline.length - 1; i++) {
  const a = pipeline[i], b = pipeline[i + 1];
  const y = -0.66;
  const z = 0.07;
  const start = new THREE.Vector3(a.x + a.w / 2 + 0.08, y, z);
  const end = new THREE.Vector3(b.x - b.w / 2 - 0.08, y, z);
  if (end.x > start.x) mainArrows.push(arrowBetween(start, end, palette.dimBlue, 0.72, 0.11));
}

const skipDefs = [
  {
    id: 'skip256',
    stage: 'decoder256',
    from: new THREE.Vector3(-5.7, blockBaseY + 2.52, 0.78),
    to: new THREE.Vector3(4.86, blockBaseY + 2.52, 0.78),
    y: blockBaseY + 3.05,
    labelX: -0.2
  },
  {
    id: 'skip128',
    stage: 'decoder128Concat',
    from: new THREE.Vector3(-4.95, blockBaseY + 1.70, 0.72),
    to: new THREE.Vector3(3.35, blockBaseY + 1.70, 0.72),
    y: blockBaseY + 2.00,
    labelX: -0.45
  },
  {
    id: 'skip64',
    stage: 'decoder64Concat',
    from: new THREE.Vector3(-4.20, blockBaseY + 0.92, 0.68),
    to: new THREE.Vector3(2.58, blockBaseY + 0.92, 0.68),
    y: blockBaseY + 1.40,
    labelX: -0.55
  },
  {
    id: 'skip32',
    stage: 'decoder32Concat',
    from: new THREE.Vector3(-3.38, blockBaseY + 0.52, 0.62),
    to: new THREE.Vector3(1.38, blockBaseY + 0.52, 0.62),
    y: blockBaseY + 0.96,
    labelX: -0.55
  }
];

const skipArrows = {};
for (const s of skipDefs) {
  const pts = [
    s.from,
    new THREE.Vector3(s.from.x + 0.9, s.y, s.from.z),
    new THREE.Vector3(s.to.x - 0.9, s.y, s.to.z),
    s.to
  ];
  skipArrows[s.id] = { ...polyArrow(pts, palette.skip, 0.9, 0.17), stage: s.stage, labelPos: new THREE.Vector3(s.labelX, s.y + 0.16, s.from.z) };
}

const timeBase = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-7.55, baselineY, 0.06),
    new THREE.Vector3(4.72, baselineY, 0.06)
  ]),
  makeLineMat(palette.time, 0.95)
);
root.add(timeBase);

const timeRing = new THREE.Mesh(
  new THREE.RingGeometry(0.22, 0.27, 36),
  makeMat(palette.time, 1)
);
timeRing.position.set(-7.38, baselineY, 0.075);
root.add(timeRing);

const injectionTargets = [enc256a, enc256b, enc128, enc64, enc32, att16, bottleneck, dec16, dec32, dec64a, dec64b, dec128, dec256a, dec256b, dec256c];
const injectionArrows = [];
for (const b of injectionTargets) {
  const start = new THREE.Vector3(b.x - 0.42, baselineY + 0.02, 0.065);
  const end = new THREE.Vector3(b.x - b.w * 0.12, blockBaseY - 0.05, 0.075);
  injectionArrows.push(arrowBetween(start, end, palette.time, 0.8, 0.10));
}

arrowBetween(new THREE.Vector3(-7.05, 2.35, 0.08), new THREE.Vector3(-6.68, 2.35, 0.08), palette.time, 0.7, 0.09);
arrowBetween(new THREE.Vector3(-7.05, 1.88, 0.08), new THREE.Vector3(-6.68, 1.88, 0.08), palette.time, 0.95, 0.09);

const halo = new THREE.LineSegments(
  new THREE.EdgesGeometry(new THREE.BoxGeometry(1, 1, 1)),
  new THREE.LineBasicMaterial({ color: palette.glow, transparent: true, opacity: 0.0 })
);
halo.visible = false;
root.add(halo);

function setHaloFor(entries) {
  const list = entries.filter(Boolean);
  if (!list.length) {
    halo.visible = false;
    return;
  }
  const box = new THREE.Box3();
  for (const e of list) box.expandByObject(e.group);
  const size = new THREE.Vector3();
  const center = new THREE.Vector3();
  box.getSize(size);
  box.getCenter(center);
  size.addScalar(0.13);
  halo.geometry.dispose();
  halo.geometry = new THREE.EdgesGeometry(new THREE.BoxGeometry(size.x, size.y, size.z));
  halo.position.copy(center);
  halo.visible = true;
}

setCameraView({
  projection: 'oblique',
  obliqueAngleDeg: 34,
  depthScale: 0.55,
  rollDeg: 0,
  heightFraction: 0.72,
  target: [-0.7, 0.25, 0.35]
});

addLabel('Res. block', new THREE.Vector3(-7.07, 2.53, 0.1), { color: '#6f8790', fontSize: '17px', bold: true });
addLabel('Res. block +<br>self-attention', new THREE.Vector3(-7.16, 1.62, 0.1), { color: '#79bdd8', fontSize: '18px', bold: true });
addLabel('t', new THREE.Vector3(-7.38, baselineY, 0.1), { color: '#8cc5dd', fontSize: '22px' });
const tLabel = addLabel('t = 500', new THREE.Vector3(-6.85, baselineY + 0.13, 0.1), { color: '#8cc5dd', fontSize: '13px', background: 'rgba(0,0,0,0.35)' });
addLabel('time embedding', new THREE.Vector3(-5.72, baselineY - 0.25, 0.1), { color: '#79bdd8', fontSize: '18px', bold: true });

for (const s of skipDefs) {
  addLabel('Concatenate', skipArrows[s.id].labelPos, { color: '#c87852', fontSize: '17px', bold: true });
}

const stageOrder = [
  'idle', 'input256', 'encoder256', 'downsample128', 'encoder128', 'downsample64',
  'encoder64', 'downsample32', 'encoder32', 'downsample16', 'attention16',
  'downsample8', 'bottleneck8', 'upsample16', 'decoder16Concat', 'upsample32',
  'decoder32Concat', 'upsample64', 'decoder64Concat', 'upsample128',
  'decoder128Concat', 'decoder256', 'output'
];

const stageInfo = {
  idle: { blocks: [], text: 'The U-Net pass is idle. Click the step button to follow the encoder, bottleneck, skip concatenations, and decoder.' },
  input256: { blocks: ['input256'], text: 'A noisy 256×256×3 image enters the U-Net. The diffusion timestep is embedded once at the lower-left node.' },
  encoder256: { blocks: ['encoder256a', 'encoder256b'], text: 'Residual blocks lift the image into 256×256×128 feature maps while preserving spatial resolution.' },
  downsample128: { blocks: ['encoder128'], arrow: 2, text: 'Downsampling halves spatial width and height to 128×128.' },
  encoder128: { blocks: ['encoder128'], text: 'The encoder processes 128×128×128 features and stores them for a matching decoder skip.' },
  downsample64: { blocks: ['encoder64'], arrow: 3, text: 'Another downsample reaches 64×64; channel depth increases.' },
  encoder64: { blocks: ['encoder64'], text: 'The 64×64 residual block carries mid-level texture and structure features.' },
  downsample32: { blocks: ['encoder32'], arrow: 4, text: 'The representation contracts to 32×32.' },
  encoder32: { blocks: ['encoder32'], text: 'At 32×32 the U-Net has a broader receptive field with compact feature maps.' },
  downsample16: { blocks: ['attention16'], arrow: 5, text: 'The path approaches the attention scale: 16×16×512.' },
  attention16: { blocks: ['attention16'], text: 'The 16×16 block adds self-attention so every token can mix information from every other spatial position.' },
  downsample8: { blocks: ['bottleneck8'], arrow: 6, text: 'A final downsample reaches the 8×8 bottleneck.' },
  bottleneck8: { blocks: ['bottleneck8'], text: 'The bottleneck is spatially tiny but semantically rich: 8×8×512 features.' },
  upsample16: { blocks: ['decoder16'], arrow: 7, text: 'The decoder starts expanding the representation back toward the image resolution.' },
  decoder16Concat: { blocks: ['decoder16', 'attention16'], skip: 'skip32', text: 'Concatenate: decoder 16×16 features reuse the matching encoder attention-scale features.' },
  upsample32: { blocks: ['decoder32'], arrow: 8, text: 'Upsampling restores 32×32 feature maps.' },
  decoder32Concat: { blocks: ['decoder32', 'encoder32'], skip: 'skip32', text: 'Concatenate: the 32×32 encoder features restore fine detail that would be lost in the bottleneck.' },
  upsample64: { blocks: ['decoder64a', 'decoder64b'], arrow: 9, text: 'The decoder upsamples to 64×64.' },
  decoder64Concat: { blocks: ['decoder64a', 'decoder64b', 'encoder64'], skip: 'skip64', text: 'Concatenate: a pulsing skip connection brings 64×64 encoder features into the decoder.' },
  upsample128: { blocks: ['decoder128'], arrow: 11, text: 'The decoder returns to 128×128 resolution.' },
  decoder128Concat: { blocks: ['decoder128', 'encoder128'], skip: 'skip128', text: 'Concatenate: 128×128 details are copied across the U shape and combined with upsampled decoder features.' },
  decoder256: { blocks: ['decoder256a', 'decoder256b', 'decoder256c', 'encoder256a', 'encoder256b'], skip: 'skip256', text: 'At 256×256 the decoder has recovered full image resolution using the earliest high-resolution encoder features.' },
  output: { blocks: ['output256'], text: 'The network outputs a noise prediction at the original image resolution.' }
};

let currentStage = 'idle';
let activeSkip = null;
let activeArrowIndex = -1;
let timestep = 500;

const passBtn = document.getElementById('passStageBtn');
const caption = document.getElementById('stageCaption');
const slider = document.getElementById('timestepSlider');
const timestepReadout = document.getElementById('timestepReadout');

function applyStage(stage) {
  currentStage = stage;
  const info = stageInfo[stage] || stageInfo.idle;
  activeSkip = info.skip || null;
  activeArrowIndex = Number.isFinite(info.arrow) ? info.arrow : -1;

  const activeIds = new Set(info.blocks || []);
  if (stage === 'idle') {
    for (const b of allBlocks) setObjectOpacity(b.group, 1);
  } else {
    for (const b of allBlocks) setObjectOpacity(b.group, activeIds.has(b.id) ? 1 : 0.35);
  }
  setHaloFor((info.blocks || []).map((id) => blockById[id]).filter(Boolean));

  caption.textContent = info.text;
  passBtn.textContent = `Step through U-Net pass: ${stage}`;
}

function updateTimestep(t) {
  timestep = Number(t);
  timestepReadout.textContent = String(timestep);
  tLabel.div.innerHTML = `t = ${timestep}`;
  const normalized = timestep / 1000;
  for (const item of badges) {
    const v = 0.5 + 0.5 * Math.sin(timestep / 75 + item.phase);
    const c = new THREE.Color().setHSL(0.55 + 0.22 * v, 0.72, 0.42 + 0.22 * normalized);
    item.mesh.material.color.copy(c);
    item.mesh.scale.setScalar(0.75 + 0.55 * v);
  }
  for (const a of injectionArrows) {
    a.mat.opacity = 0.45 + 0.5 * normalized;
    a.coneMat.opacity = 0.45 + 0.5 * normalized;
  }
}

passBtn.addEventListener('click', () => {
  const idx = stageOrder.indexOf(currentStage);
  applyStage(stageOrder[(idx + 1) % stageOrder.length]);
});

slider.addEventListener('input', () => updateTimestep(slider.value));

const demoSteps = [
  {
    title: 'Conditioned input',
    narration: 'The noisy image enters the U-Net at 256×256 resolution. The timestep t is embedded once, then injected into every processing block along the encoder and decoder.',
    state: { passStage: 'input256', timestep: 500 }
  },
  {
    title: 'Encoder downsamples',
    narration: 'The left branch repeatedly applies residual blocks while reducing spatial size from 256×256 to 128×128, 64×64, and 32×32. The blocks become shorter to show shrinking spatial resolution while channel depth increases.',
    state: { passStage: 'encoder32', timestep: 500 }
  },
  {
    title: 'Self-attention at 16×16',
    narration: 'Near the bottleneck, the 16×16 block adds self-attention. This is the scale where global spatial relationships can be modeled without the cost of attending over the full 256×256 image.',
    state: { passStage: 'attention16', timestep: 500 }
  },
  {
    title: 'Bottleneck',
    narration: 'At 8×8, the representation is spatially compact but semantically rich. The network has compressed the noisy input into a low-resolution feature description.',
    state: { passStage: 'bottleneck8', timestep: 500 }
  },
  {
    title: 'Decoder uses skip connections',
    narration: 'As the decoder upsamples, matching encoder features are concatenated back in. The pulsing orange skip arrow marks the Concatenate operation that restores fine spatial detail at the current scale.',
    state: { passStage: 'decoder64Concat', timestep: 500 }
  },
  {
    title: 'Change the diffusion time',
    narration: 'Move t to a later denoising step. The same U-Net geometry is used, but the time-embedding values injected into every residual block change, conditioning the predicted noise on the current diffusion step.',
    state: { passStage: 'decoder128Concat', timestep: 850 }
  }
];

function tweenTimestep(target) {
  const start = timestep;
  const end = Number(target);
  const t0 = performance.now();
  function step(now) {
    const u = Math.min(1, (now - t0) / 550);
    const eased = u * u * (3 - 2 * u);
    const val = Math.round(start + (end - start) * eased);
    slider.value = val;
    updateTimestep(val);
    if (u < 1) requestAnimationFrame(step);
  }
  requestAnimationFrame(step);
}

function goToStep(i) {
  const step = demoSteps[i];
  if (!step) return;
  document.getElementById('demoNarration').innerHTML = `<b>${step.title}</b><br>${step.narration}`;
  applyStage(step.state.passStage);
  tweenTimestep(step.state.timestep);
}

window.goToStep = goToStep;

document.querySelectorAll('.demoBtn').forEach((btn) => {
  btn.addEventListener('click', () => goToStep(Number(btn.dataset.step)));
});

function makeTextSpriteLikeLabel(text, pos, color = '#ffffff', size = '12px') {
  return addLabel(text, pos, { color, fontSize: size, background: 'rgba(0,0,0,0.55)' });
}

let overlayGroup = null;
let overlayShown = false;

function makeOverlay() {
  const g = new THREE.Group();
  g.position.set(-1.05, 1.32, 0.96);

  const panel = new THREE.Mesh(
    new THREE.PlaneGeometry(3.2, 1.55),
    new THREE.MeshBasicMaterial({ color: 0x071014, transparent: true, opacity: 0.88, side: THREE.DoubleSide })
  );
  panel.position.set(0, 0, -0.02);
  g.add(panel);

  const panelEdge = new THREE.LineSegments(
    new THREE.EdgesGeometry(new THREE.PlaneGeometry(3.2, 1.55)),
    makeLineMat(palette.skip, 1)
  );
  panelEdge.position.copy(panel.position);
  g.add(panelEdge);

  const tokenGeom = new THREE.PlaneGeometry(0.035, 0.035);
  const tokenMat = new THREE.MeshBasicMaterial({ color: 0x6eb6d0, transparent: true, opacity: 0.92, side: THREE.DoubleSide });
  const tokens = new THREE.InstancedMesh(tokenGeom, tokenMat, 256);
  const dummy = new THREE.Object3D();
  let idx = 0;
  const gridOrigin = new THREE.Vector3(-1.32, -0.42, 0.02);
  const gap = 0.052;
  const tokenPositions = [];
  for (let r = 0; r < 16; r++) {
    for (let c = 0; c < 16; c++) {
      dummy.position.set(gridOrigin.x + c * gap, gridOrigin.y + r * gap, 0.02);
      dummy.updateMatrix();
      tokens.setMatrixAt(idx++, dummy.matrix);
      tokenPositions.push(dummy.position.clone());
    }
  }
  g.add(tokens);

  const query = tokenPositions[8 * 16 + 8];
  const faintPts = [];
  for (const p of tokenPositions) {
    faintPts.push(query.clone(), p.clone());
  }
  const links = new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(faintPts),
    makeLineMat(0x79bdd8, 0.13)
  );
  links.position.z = 0.035;
  g.add(links);

  const hotPts = [];
  [5, 29, 47, 124, 170, 219, 250].forEach((i) => {
    hotPts.push(query.clone(), tokenPositions[i].clone());
  });
  const hotLinks = new THREE.LineSegments(
    new THREE.BufferGeometry().setFromPoints(hotPts),
    makeLineMat(palette.skip, 0.95)
  );
  hotLinks.position.z = 0.052;
  g.add(hotLinks);

  const plainBaseX = 0.62;
  for (let i = 0; i < 3; i++) {
    const box = new THREE.Mesh(
      new THREE.BoxGeometry(0.34, 0.32, 0.08),
      makeMat(i === 1 ? palette.copperTop : palette.copperFront, 0.95)
    );
    box.position.set(plainBaseX + i * 0.46, -0.05, 0.04);
    g.add(box);
    g.add(new THREE.LineSegments(new THREE.EdgesGeometry(box.geometry), makeLineMat(0x000000, 1))).children.at(-1)?.position.copy(box.position);
    if (i < 2) arrowBetween(
      new THREE.Vector3(plainBaseX + i * 0.46 + 0.21, -0.05, 0.08),
      new THREE.Vector3(plainBaseX + (i + 1) * 0.46 - 0.21, -0.05, 0.08),
      0xdddddd,
      0.85,
      0.08,
      g
    );
  }

  const localPts = [];
  const lx = plainBaseX + 0.46;
  for (let r = -1; r <= 1; r++) {
    for (let c = -1; c <= 1; c++) {
      localPts.push(new THREE.Vector3(lx, -0.52, 0.08), new THREE.Vector3(lx + c * 0.065, -0.52 + r * 0.065, 0.08));
    }
  }
  g.add(new THREE.LineSegments(new THREE.BufferGeometry().setFromPoints(localPts), makeLineMat(0xffd166, 0.75)));

  makeTextSpriteLikeLabel('Self-attention: one 16×16 token can read all positions', new THREE.Vector3(-1.62, 2.20, 1.02), '#d5f5ff', '12px');
  makeTextSpriteLikeLabel('Plain Res. block: local convolutional path', new THREE.Vector3(0.78, 2.20, 1.02), '#ffd6c6', '12px');

  return g;
}

function toggleAttentionOverlay(force) {
  const next = force === undefined ? !overlayShown : !!force;
  if (next === overlayShown) return;
  overlayShown = next;
  if (overlayShown) {
    if (!overlayGroup) overlayGroup = makeOverlay();
    scene.add(overlayGroup);
    applyStage('attention16');
    showPopup(
      '16×16 self-attention',
      'Self-attention treats the 16×16 feature map as 256 tokens. A query token can mix information from every key token, whereas the plain residual path mainly combines nearby convolutional neighborhoods.'
    );
  } else {
    if (overlayGroup) scene.remove(overlayGroup);
    hidePopup();
  }
}

registerInteractive(att16.group, {
  title: '16×16 Res. block + self-attention',
  tooltip: 'Click to inspect all-to-all attention at the 16×16 scale',
  body: 'This block is spatially small enough that self-attention over 16×16 = 256 tokens is affordable, giving the denoiser access to global image relationships.',
  onClick: () => toggleAttentionOverlay()
});

document.getElementById('inspectAttentionBtn').addEventListener('click', () => toggleAttentionOverlay());

const outsideRaycaster = new THREE.Raycaster();
const outsidePointer = new THREE.Vector2();
canvas.addEventListener('click', (event) => {
  if (!overlayShown) return;
  const rect = canvas.getBoundingClientRect();
  outsidePointer.x = ((event.clientX - rect.left) / rect.width) * 2 - 1;
  outsidePointer.y = -((event.clientY - rect.top) / rect.height) * 2 + 1;
  outsideRaycaster.setFromCamera(outsidePointer, camera);
  const hitsAttention = outsideRaycaster.intersectObject(att16.group, true).length > 0;
  const hitsOverlay = overlayGroup && outsideRaycaster.intersectObject(overlayGroup, true).length > 0;
  if (!hitsAttention && !hitsOverlay) toggleAttentionOverlay(false);
});

function pulseLoop(now) {
  const s = 0.5 + 0.5 * Math.sin(now * 0.006);
  halo.material.opacity = halo.visible ? 0.45 + 0.35 * s : 0;

  for (const [id, sk] of Object.entries(skipArrows)) {
    const active = id === activeSkip;
    const op = active ? 0.45 + 0.55 * s : 0.34;
    sk.mat.opacity = op;
    sk.coneMat.opacity = op;
  }

  mainArrows.forEach((a, i) => {
    const active = i === activeArrowIndex;
    const op = active ? 0.45 + 0.55 * s : 0.55;
    a.mat.opacity = op;
    a.coneMat.opacity = op;
    a.mat.color.set(active ? palette.glow : palette.dimBlue);
    a.coneMat.color.set(active ? palette.glow : palette.dimBlue);
  });

  requestAnimationFrame(pulseLoop);
}

updateTimestep(500);
applyStage('idle');
requestAnimationFrame(pulseLoop);
